parameters.jsCode:
// Получаем параметры пагинации из первого узла Code
const pagination = $('Подготовка параметров').first().json; 
let messages = $input.all().map(item => item.json);

// Проверяем fallback-сценарий (когда Always Output Data генерирует пустой объект {})
if (messages.length === 1 && Object.keys(messages[0]).length === 0) {
  messages = []; // Очищаем массив, так как реальных данных нет
}

// Если история не найдена, возвращаем fallback-ответ
if (messages.length === 0) {
  return {
    success: true,
    page: pagination.page,
    limit: pagination.limit,
    total_returned: 0,
    message: "История чата не найдена для указанного session_id.",
    data: []
  };
}

const deleteStatus = (message) => {
  let statusRegex = /^(?:\*\*|#|[ \t])*STATUS:[ \t]*(?:\*\*|#|[ \t])*(PASSED|FAILED)(?:\*\*|#|[ \t])*/im;
  let statusMatch = message.match(statusRegex);
  if (statusMatch) message = message.replace(statusRegex, '').trim();
  return message;
}

const parsedMessages = messages.map(msg => {
  let msgData = {};
  try {
    msgData = typeof msg.message === 'string'
      ? JSON.parse(msg.message)
      : (msg.message || {});
  } catch(e) {}
  const msgType = msgData.type || null;
  return {
    id: msg.id,
    type: msgType,
    content: msgType === "human"
      ? (msgData.content || null)
      : (deleteStatus(msgData.content) || null),
    action: msgData.additional_kwargs?.action || null,
    timestamp: msgData.additional_kwargs?.timestamp || null,
    files: msgData.additional_kwargs?.files || []
  };
});

// Стандартный ответ при наличии данных
return {
  success: true,
  page: pagination.page,
  limit: pagination.limit,
  total_returned: messages.length,
  data: parsedMessages,
};

const query = $('Chat history').first().json.query || {};

const sessionId = query.sessionId;
if (!sessionId) throw new Error("ОШИБКА: Параметр sessionId обязателен");

const page = Math.max(parseInt(query.page) || 1, 1);

let limit = parseInt(query.limit) || 10;
limit = Math.min(Math.max(limit, 1), 50);

const offset = (page - 1) * limit;

return { sessionId, limit, offset, page };

