CREATE TABLE IF NOT EXISTS ai_agent_metadata (
  id       SERIAL PRIMARY KEY,
  session_id CHARACTER VARYING(255),
  message  JSONB
);

CREATE INDEX IF NOT EXISTS idx_ai_agent_metadata_session
  ON ai_agent_metadata(session_id);

INSERT INTO ai_agent_metadata (session_id, message)
VALUES (
  $1,
  jsonb_build_object(
    'type', 'ai',
    'content', convert_from(decode($2, 'base64'), 'UTF8'),
    'additional_kwargs', jsonb_build_object(
      'timestamp', EXTRACT(EPOCH FROM NOW())::bigint * 1000
    ),
    'response_metadata', '{}'::jsonb
  )
);

